import{esc,button,input,select}from'../phase4/ui.js';
import{decimalPlaces,fmt,width,digits,placeLabel,rowLabel,rowOffset,origin,location,number,estimateBounds}from'./b11-model.js';
const s=t=>t.scale||1;
const f=(key,label,value)=>input(key,label,value,'autocomplete="off" spellcheck="false" inputmode="decimal"');
const operation=t=>t.op==='+'?'＋':'−';
function writtenControls(t,m){
 if(!t.written)return'';
 // Older prototype drafts keep their real exchanges and gain empty writing cells.
 m.columnAnswers??=Array(width(t)).fill('');
 const cols=Array.from({length:width(t)},(_,k)=>width(t)-1-k);
 return`<fieldset class="b11-written"><legend>把换好的结果按列写下来</legend><p class="muted">每列写一位。最左边多出的空列可以留空，其他空位要写0。</p><div class="b11-written-row" style="--cols:${width(t)}">${cols.map(i=>`<label class="b11-written-cell ${s(t)>1&&i===decimalPlaces(s(t))?'decimal-edge':''}"><span>${placeLabel(t,i)}</span><input type="text" maxlength="1" inputmode="numeric" pattern="[0-9]" autocomplete="off" data-xfield="columnAnswers.${i}" aria-label="${placeLabel(t,i)}这一列的结果" value="${esc(m.columnAnswers[i])}"></label>`).join('')}</div></fieldset>`;
}
const history=rows=>`<div class="b11-records">${rows.map(row=>`<span>${esc(row)}</span>`).join('')}</div>`;
const tokens=(n,i,t)=>`<div class="b11-tokens" aria-label="${n}份${placeLabel(t,i)}">${Array.from({length:Math.min(n,100)},()=>`<i class="b11-token tone-${i%3}"></i>`).join('')||'<span class="b11-empty">空着</span>'}</div>`;
function row(t,m,index){const label=rowLabel(t,index),offset=m.align[index],w=width(t);if(offset==='')return`<div class="b11-unplaced"><b>${esc(label)}</b><span>还没放到格子里</span></div>`;const raw=t.values[index]/10**rowOffset(t,index),cs=digits(raw,w),shift=Number(offset);return`<div class="b11-digit-row" style="--cols:${w}">${Array.from({length:w},(_,k)=>w-1-k).map(i=>`<span class="${s(t)>1&&i===decimalPlaces(s(t))?'decimal-edge':''}">${i<shift?'':cs[i-shift]||i-shift<String(raw).length?cs[i-shift]:''}</span>`).join('')}</div>`;}
function placeBoard(t,m){const w=width(t),cols=Array.from({length:w},(_,k)=>w-1-k);return`<div class="b11-scroll"><div class="b11-place-board" style="--cols:${w}"><div class="b11-column-head">${cols.map(i=>`<span class="${s(t)>1&&i===decimalPlaces(s(t))?'decimal-edge':''}">${placeLabel(t,i)}</span>`).join('')}</div>${t.values.map((_,i)=>`<div class="b11-source-row"><span class="b11-sign">${i?operation(t):''}</span>${row(t,m,i)}</div>`).join('')}${m.started?`<div class="b11-columns">${cols.map(i=>`<section class="b11-column ${s(t)>1&&i===decimalPlaces(s(t))?'decimal-edge':''}">${tokens(m.counts[i],i,t)}<b>${m.counts[i]}份</b><div class="b11-exchanges">${i<w-1?button('b11-exchange','十份合一份',`data-index="${i}" data-dir="up" aria-label="十份${placeLabel(t,i)}合成一份${placeLabel(t,i+1)}" ${m.counts[i]<10?'disabled':''}`):''}${i>0?button('b11-exchange','一份拆成十份',`data-index="${i}" data-dir="down" aria-label="一份${placeLabel(t,i)}拆成十份${placeLabel(t,i-1)}" ${!m.counts[i]?'disabled':''}`):''}${t.op==='-'?button('b11-remove',m.remaining[i]?`拿走 ${m.remaining[i]} 份`:'这里拿好了',`data-index="${i}" aria-label="拿走${placeLabel(t,i)}这一列" ${!m.remaining[i]?'disabled':''}`):''}</div></section>`).join('')}</div>`:''}</div></div>`;}
function routeVisual(t,m){const hops=m.hops,all=[origin(t),...hops.map(h=>h.to)],min=Math.min(...all),max=Math.max(...all),span=max-min||1,x=n=>55+(n-min)/span*670;return`<div class="b11-line-wrap"><svg viewBox="0 0 780 190" role="img" aria-label="从${fmt(origin(t),s(t))}出发，留下${hops.length}步"><path class="b11-axis" d="M30 140H750"/>${hops.map((h,i)=>{const from=i?hops[i-1].to:origin(t),x1=x(from),x2=x(h.to),high=30+(i%3)*28;return`<path class="b11-hop ${h.delta<0?'back':''}" d="M${x1} 140 Q${(x1+x2)/2} ${high} ${x2} 140"/><text x="${(x1+x2)/2}" y="${(high+140)/2-8}" text-anchor="middle">${h.delta>0?'+':''}${fmt(h.delta,s(t))}</text>`;}).join('')}${[...new Set(all)].map(n=>`<circle cx="${x(n)}" cy="140" r="5"/><text x="${x(n)}" y="167" text-anchor="middle">${fmt(n,s(t))}</text>`).join('')}</svg></div><p class="b11-current">现在在 <strong>${fmt(location(t,m),s(t))}</strong></p>`+history(hops.map((h,i)=>`${i+1} · ${fmt(i?hops[i-1].to:origin(t),s(t))} ${h.delta>=0?'＋':'−'} ${fmt(Math.abs(h.delta),s(t))} → ${fmt(h.to,s(t))}`));}
export function visual(t,m){switch(t.type){
 case'x-placecalc':return`<p class="b11-equation">${t.values.map((_,i)=>esc(rowLabel(t,i))).join(` ${operation(t)} `)}</p>${placeBoard(t,m)}${m.first!==null?`<p class="muted">最初猜 ${esc(m.first)}。换一换单位，总量不会凭空变化。</p>`:'<p class="muted">先猜，再把同样大小的单位放在同一列。</p>'}`;
 case'x-routecalc':return`<p class="b11-equation">${fmt(t.a,s(t))} ${operation(t)} ${fmt(t.b,s(t))}</p>${t.countup?`<p>从 ${fmt(t.b,s(t))} 接到 ${fmt(t.a,s(t))}，走过的距离就是相差多少。</p>`:''}${routeVisual(t,m)}${m.first!==null?`<p class="muted">最初猜 ${esc(m.first)}。可以改路线，原来的尝试也会留下。</p>`:''}`;
 case'x-groupfour':return`<div class="b11-groups">${m.groups.map((g,i)=>`<section class="${m.selected.includes(i)?'selected':''}">${button('b11-group-pick',String(g.value),`data-index="${i}" aria-label="选这一堆${g.value}" aria-pressed="${m.selected.includes(i)}" ${m.groups.length===1?'disabled':''}`)}<div class="b11-pieces">${g.ids.map(id=>`<span class="tone-${id%3}">${t.values[id]}</span>`).join('')}</div></section>`).join('')}</div><p class="muted">${m.groups.length===1?'每一份都汇合进来了。':'先选两堆，看看合起来多少。还没选的继续留在桌上。'}</p>`+history(m.merges.map(r=>`${r.left.value} ＋ ${r.right.value} = ${r.answer}`));
 case'x-storyledger':{const step=t.steps[m.cursor],current=m.cursor?m.saved.at(-1).result:fmt(t.start,s(t));return`<div class="b11-story"><span>现在留下</span><strong>${esc(current)} <small>${esc(t.unit||'')}</small></strong>${step?`<p class="b11-event">${esc(step.text)}</p><span class="muted">第 ${m.cursor+1} 件事 / ${t.steps.length}</span>`:'<p>这几件事已经全部接起来了。</p>'}</div>`+history(m.saved.map((r,i)=>`${i+1} · ${i?m.saved[i-1].result:fmt(t.start,s(t))} ${r.op==='+'?'＋':'−'} ${r.amount} = ${r.result}`));}
 case'x-estimatecheck':{const l=m.locked;let extra='';if(l&&t.claimed!==undefined){const b=estimateBounds(t,Number(l.unit));extra=`<div class="b11-claim"><p>有人说结果是 <strong>${fmt(t.claimed,s(t))}</strong>。</p><p>只看取近似数留下的范围：${b.lowerInclusive?'不小于':'大于'} ${fmt(b.low,s(t))}，小于 ${fmt(b.high,s(t))}。</p><p class="muted">在范围内只表示还不能排除，仍要精算检查。</p></div>`;}return`<p class="b11-equation">${fmt(t.a,s(t))} ${operation(t)} ${fmt(t.b,s(t))}</p>${l?`<div class="b11-estimate"><span>你先留下的粗略结果</span><strong>${esc(l.roundedA)} ${operation(t)} ${esc(l.roundedB)} ≈ ${esc(l.estimate)}</strong></div>${extra}`:'<p>先给结果找个大致范围，再精算和倒着检查。</p>'}`;}
}return'';}
export function controls(t,m){switch(t.type){
 case'x-placecalc':return !m.started?f('guess','先猜最后有多少',m.guess)+`<div class="b11-align">${t.values.map((_,i)=>select(`align.${i}`,`${rowLabel(t,i)} 最后一位放在`,m.align[i],Array.from({length:width(t)},(_,j)=>[String(j),placeLabel(t,j)]))).join('')}</div>`+button('b11-place-start',t.op==='+'?'把对齐的几堆合起来':'摆好原来的数量，准备拿走'):writtenControls(t,m)+f('answer','换好、拿好以后是多少',m.answer);
 case'x-routecalc':return !m.started?f('guess','先猜结果是多少',m.guess)+button('b11-route-start','留下猜想，开始走'):f('jump','这一步变化多少（向回走填负数）',m.jump)+f('landing','走完这一步，到哪里',m.landing)+button('b11-hop','走这一步')+button('b11-hop-undo','退回刚才那一步',!m.hops.length?'disabled':'')+f('answer',t.countup?'两边相差多少':'整个变化的结果',m.answer);
 case'x-groupfour':return m.groups.length>1?f('subtotal','选的这两堆合起来是多少',m.subtotal)+button('b11-group-merge','把这两堆合起来',m.selected.length!==2?'disabled':''):'';
 case'x-storyledger':return m.cursor<t.steps.length?select('op','这件事让数量怎样变',m.op,[['+','增加'],['-','减少']])+f('amount','变化多少',m.amount)+f('result','现在剩下多少',m.result)+select('method','你这一步用了什么办法',m.method,[['mental','在心里想'],['written','画一画或写下来'],['tool','借助计算工具']])+button('b11-event','留下这件事，再接着走'):'';
 case'x-estimatecheck':return !m.locked?select('unit','先取到多细',m.unit,t.units.map(u=>[String(u),`每隔 ${fmt(u,s(t))} 取一个近似数`]))+f('roundedA','第一个数靠近哪里',m.roundedA)+f('roundedB','第二个数靠近哪里',m.roundedB)+f('estimate','粗略算起来是多少',m.estimate)+button('b11-estimate','先把这个估计留下'):f('answer','现在精算，结果是多少',m.answer)+`<fieldset class="b11-inverse"><legend>倒着检查一次</legend>${f('inverseStart','从刚算出的结果出发',m.inverseStart)}${select('inverseOp','用相反的动作',m.inverseOp,[['+','加回来'],['-','拿走']])}${f('inversePart','用原来的哪一份',m.inversePart)}${f('inverseResult','倒着检查回到了多少',m.inverseResult)}</fieldset>`+(t.claimed!==undefined?select('judgment','刚才那个人的答案怎样',m.judgment,[['plausible','在范围内，还需要精算确认'],['impossible','已经超出范围，可以排除']]):'');
}return'';}
export const render=(t,m)=>`<section class="b11-work"><div id="extra-visual">${visual(t,m)}</div><div id="extra-controls">${controls(t,m)}${m.issue?`<p role="status" class="b11-issue">${esc(m.issue)}</p>`:''}</div></section>`;
